"use client";

import * as React from "react";
import { GitBranch, Vote } from "lucide-react";

import { cn } from "@/lib/utils";
import {
  FileViewer,
  FileViewerContent,
  FileViewerControls,
  FileViewerHeader,
  FileViewerInset,
  FileViewerLegend,
  FileViewerProvider,
  FileViewerSidebar,
  FileViewerSidebarContent,
  FileViewerSidebarHeader,
  FileViewerSidebarTrigger,
  FileViewerTitle,
} from "@/components/ui/file-viewer";
import { Label } from "@/components/ui/label";
import { PdfViewerPages, PdfViewerProvider } from "@/components/ui/pdf-viewer";
import { Switch } from "@/components/ui/switch";
import type {
  SplitResult,
  SplitSubdocumentLikelihood,
  SplitView,
} from "@/components/viewers/lib/split-types";
import {
  SplitViewerDocument,
  SplitViewerLegend,
  SplitViewerPageRail,
  SplitViewerProvider,
  useSplitViewerDocumentControls,
} from "@/components/viewers/split/split-viewer";

const PDF_SOURCE = {
  kind: "url" as const,
  url: "/samples/an-image-is-worth-16x16-words.pdf",
  fileName: "an-image-is-worth-16x16-words.pdf",
};

const SPLIT_OUTPUT: SplitResult[] = [
  { name: "Title, Abstract & Introduction", pages: [1] },
  { name: "Related Work", pages: [2] },
  { name: "Method", pages: [3] },
  { name: "Experiments", pages: pages(4, 8) },
  { name: "Conclusion", pages: [9] },
  { name: "References", pages: pages(10, 12) },
  { name: "Appendix", pages: pages(13, 22) },
];

const SPLIT_CONSENSUS_CHOICES: SplitResult[][] = [
  SPLIT_OUTPUT,
  [
    { name: "Title, Abstract & Introduction", pages: [1] },
    { name: "Related Work", pages: [2] },
    { name: "Method", pages: [3, 4] },
    { name: "Experiments", pages: pages(5, 8) },
    { name: "Conclusion & References", pages: pages(9, 12) },
    { name: "Appendix", pages: pages(13, 22) },
  ],
  [
    { name: "Title, Abstract & Introduction", pages: [1] },
    { name: "Related Work", pages: [2] },
    { name: "Method", pages: [3] },
    { name: "Experiments", pages: pages(4, 8) },
    { name: "Conclusion", pages: [9] },
    { name: "References", pages: pages(10, 12) },
    { name: "Appendix", pages: pages(13, 22) },
  ],
];

const SPLIT_CONSENSUS_LIKELIHOODS: SplitSubdocumentLikelihood[] = [
  { name: 0.98, pages: [0.98] },
  { name: 0.92, pages: [0.91] },
  { name: 0.89, pages: [0.86] },
  { name: 0.95, pages: [0.96, 0.95, 0.95, 0.94, 0.96] },
  { name: 0.8, pages: [0.77] },
  { name: 0.82, pages: [0.81, 0.83, 0.82] },
  {
    name: 0.99,
    pages: [0.98, 0.98, 0.99, 0.98, 0.99, 0.99, 0.98, 0.98, 0.99, 0.98],
  },
];

const SPLIT_RESULT: SplitView = {
  output: SPLIT_OUTPUT,
  consensus: {
    choices: SPLIT_CONSENSUS_CHOICES,
    likelihoods: SPLIT_CONSENSUS_LIKELIHOODS,
  },
  usage: { credits: 3 },
};

const SINGLE_PASS_SPLIT_RESULT: SplitView = {
  output: SPLIT_OUTPUT,
  consensus: { choices: [], likelihoods: null },
  usage: { credits: 1 },
};

export function SplitConsensusViewerBlock() {
  const [isConsensusEnabled, setIsConsensusEnabled] = React.useState(true);
  const result = isConsensusEnabled ? SPLIT_RESULT : SINGLE_PASS_SPLIT_RESULT;

  return (
    <div className="bg-background flex h-full min-h-[680px] flex-col">
      <SplitViewerProvider result={result}>
        <FileViewerProvider source={PDF_SOURCE} defaultSidebarOpen>
          <FileViewer className="bg-background">
            <PdfViewerProvider>
              <FileViewerHeader>
                <FileViewerSidebarTrigger className="-ms-1" />
                <FileViewerTitle />
                <FileViewerControls />
              </FileViewerHeader>
              <FileViewerContent>
                <SplitConsensusSidebar
                  isConsensusEnabled={isConsensusEnabled}
                  onConsensusEnabledChange={setIsConsensusEnabled}
                />
                <FileViewerInset>
                  <FileViewerLegend>
                    <SplitViewerLegend className="px-3 py-2" />
                  </FileViewerLegend>
                  <SplitViewerDocument document={<SplitConsensusDocument />} />
                </FileViewerInset>
              </FileViewerContent>
            </PdfViewerProvider>
          </FileViewer>
        </FileViewerProvider>
      </SplitViewerProvider>
    </div>
  );
}

function SplitConsensusSidebar({
  isConsensusEnabled,
  onConsensusEnabledChange,
}: {
  isConsensusEnabled: boolean;
  onConsensusEnabledChange: (enabled: boolean) => void;
}) {
  return (
    <FileViewerSidebar
      aria-label="Split consensus"
      width="19rem"
      className="border-r"
    >
      <FileViewerSidebarHeader className="min-h-12">
        <Label
          htmlFor="split-consensus-switch"
          className="flex min-w-0 flex-1 items-center gap-2 text-sm font-medium"
        >
          <GitBranch className="text-muted-foreground size-4 shrink-0" />
          <span className="truncate">Consensus</span>
        </Label>
        <Switch
          id="split-consensus-switch"
          checked={isConsensusEnabled}
          onCheckedChange={onConsensusEnabledChange}
          size="sm"
        />
      </FileViewerSidebarHeader>
      <FileViewerSidebarContent className="overflow-hidden">
        <div className="grid min-h-0 flex-1 grid-cols-[4.5rem_minmax(0,1fr)]">
          <div className="min-h-0 border-r">
            <SplitViewerPageRail />
          </div>
          <SplitConsensusDetails isConsensusEnabled={isConsensusEnabled} />
        </div>
      </FileViewerSidebarContent>
    </FileViewerSidebar>
  );
}

function SplitConsensusDetails({
  isConsensusEnabled,
}: {
  isConsensusEnabled: boolean;
}) {
  return (
    <div className="min-h-0 overflow-auto px-3 py-3">
      <div className="text-muted-foreground mb-3 flex items-center justify-between gap-3 text-xs">
        <span className="font-mono">
          n_consensus={isConsensusEnabled ? 3 : 1}
        </span>
        <span>{SPLIT_OUTPUT.length} segments</span>
      </div>

      <div className="space-y-1.5">
        {SPLIT_OUTPUT.map((segment, index) => {
          const likelihood = isConsensusEnabled
            ? SPLIT_CONSENSUS_LIKELIHOODS[index]
            : null;
          return (
            <div
              key={segment.name}
              className="border-border/70 bg-background rounded-md border px-2 py-1.5"
            >
              <div className="flex min-w-0 items-center justify-between gap-2">
                <span className="min-w-0 truncate text-xs font-medium">
                  {segment.name}
                </span>
                {likelihood ? (
                  <span
                    className={cn(
                      "shrink-0 rounded-sm px-1.5 py-0.5 text-[10px] font-medium tabular-nums",
                      getConfidenceClassName(meanLikelihood(likelihood)),
                    )}
                  >
                    {formatPercent(meanLikelihood(likelihood))}
                  </span>
                ) : null}
              </div>
              <div className="text-muted-foreground mt-1 font-mono text-[10px]">
                p. {formatPageList(segment.pages)}
              </div>
            </div>
          );
        })}
      </div>

      {isConsensusEnabled ? (
        <div className="mt-4 space-y-2">
          <div className="text-muted-foreground flex items-center gap-2 text-xs font-medium">
            <Vote className="size-3.5" />
            <span>Votes</span>
          </div>
          {SPLIT_CONSENSUS_CHOICES.map((choice, choiceIndex) => (
            <div
              key={choiceIndex}
              className="border-border/70 rounded-md border px-2 py-1.5"
            >
              <div className="text-xs font-medium">Run {choiceIndex + 1}</div>
              <div className="text-muted-foreground mt-1 line-clamp-2 text-[11px] leading-4">
                {choice
                  .map(
                    (segment) =>
                      `${segment.name}: ${formatPageList(segment.pages)}`,
                  )
                  .join(" | ")}
              </div>
            </div>
          ))}
        </div>
      ) : null}
    </div>
  );
}

function SplitConsensusDocument() {
  const controls = useSplitViewerDocumentControls();

  return (
    <PdfViewerPages
      ref={controls.setDocumentHandle}
      bare
      onVisiblePageChange={controls.onCurrentPageChange}
      onScrollProgressChange={controls.onScrollProgressChange}
      className="h-full"
    />
  );
}

function pages(start: number, end: number) {
  return Array.from({ length: end - start + 1 }, (_, index) => start + index);
}

function meanLikelihood(likelihood: SplitSubdocumentLikelihood) {
  const values = [
    typeof likelihood.name === "number" ? likelihood.name : null,
    ...(likelihood.pages ?? []),
  ].filter((value): value is number => typeof value === "number");
  if (values.length === 0) return null;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

function formatPercent(value: number | null) {
  if (value === null) return "n/a";
  return `${Math.round(value * 100)}%`;
}

function getConfidenceClassName(value: number | null) {
  if (value === null) return "bg-muted text-muted-foreground";
  if (value >= 0.9) return "bg-emerald-500/12 text-emerald-700";
  if (value >= 0.8) return "bg-amber-500/12 text-amber-700";
  return "bg-destructive/10 text-destructive";
}

function formatPageList(pages: readonly number[]) {
  if (pages.length === 0) return "none";
  const ranges: string[] = [];
  let start = pages[0]!;
  let previous = pages[0]!;

  for (const page of pages.slice(1)) {
    if (page === previous + 1) {
      previous = page;
      continue;
    }
    ranges.push(start === previous ? `${start}` : `${start}-${previous}`);
    start = page;
    previous = page;
  }

  ranges.push(start === previous ? `${start}` : `${start}-${previous}`);
  return ranges.join(", ");
}

// Partition result shapes, mirrored from the Retab API / dashboard.

export interface PartitionChunk {
  key: string;
  /** 1-indexed pages assigned to this chunk. */
  pages: number[];
}

export interface PartitionChunkLikelihood {
  key: number | null;
  pages: number[];
}

export interface PartitionConsensus {
  choices: PartitionChunk[][];
  likelihoods: PartitionChunkLikelihood[] | null;
}

export interface PartitionUsage {
  credits: number;
}

export interface PartitionResult {
  output: PartitionChunk[];
  consensus: PartitionConsensus;
  usage: PartitionUsage | null;
}

// Split result shapes (the structural subset the viewer needs), mirrored from
// the Retab dashboard's SplitView.

import type { PartitionChunk } from "@/components/viewers/lib/partition-types";

export interface SplitResult {
  name: string;
  /** 1-indexed pages assigned to this subdocument. */
  pages: number[];
  /** Frontend-only overlay carried through by the split viewer. */
  partitions?: PartitionChunk[];
}

export interface SplitSubdocumentLikelihood {
  /** Consensus confidence for the subdocument label. */
  name?: number | null;
  /** Consensus confidence per assigned page, aligned with the output pages. */
  pages?: number[] | null;
}

export interface SplitViewConsensus {
  choices?: SplitResult[][];
  likelihoods?: SplitSubdocumentLikelihood[] | null;
}

export interface SplitView {
  output: SplitResult[];
  consensus?: SplitViewConsensus | null;
  usage?: { credits: number } | null;
}

export function asSplitView(
  payload:
    | { output?: unknown; consensus?: unknown; usage?: unknown }
    | null
    | undefined,
): SplitView | null {
  if (!payload || !Array.isArray(payload.output)) return null;
  return {
    output: payload.output as SplitResult[],
    consensus: (payload.consensus ?? null) as SplitViewConsensus | null,
    usage: (payload.usage ?? null) as SplitView["usage"],
  };
}

export function getSplitVotes(
  splitView: SplitView | null | undefined,
  splitIndex: number,
): SplitResult[] {
  const choices = splitView?.consensus?.choices;
  if (!choices?.length) return [];
  return choices.flatMap((choice) => {
    const split = choice[splitIndex];
    return split ? [split] : [];
  });
}

"use client";

import * as React from "react";
import { type ReactNode } from "react";
import { Loader2, Scissors } from "lucide-react";

import { segmentsPageCount, toSegments } from "@/lib/segments";
import { cn } from "@/lib/utils";
import type { ViewerSource } from "@/lib/viewer-source";
import {
  FileViewerContent,
  FileViewerHeader,
  FileViewerTitle,
  FileViewerLegend,
  FileViewer,
  FileViewerProvider,
  FileViewerSidebar,
  FileViewerSidebarContent,
  FileViewerSidebarTrigger,
  FileViewerInset,
  FileViewerControls,
  FileViewerViewport,
} from "@/components/ui/file-viewer";
import { SegmentLegend } from "@/components/ui/segment-legend";
import { SegmentPageRail } from "@/components/ui/segment-page-rail";
import {
  createSegmentedDocumentModel,
  type DocumentSegment,
  type SegmentedDocumentModel,
} from "@/components/ui/segmented-document-model";
import {
  SegmentedDocumentProvider,
  useSegmentedDocumentViewport,
} from "@/components/ui/segmented-document-provider";
import {
  type SegmentDocumentHandle,
  type SegmentViewportController,
} from "@/components/ui/use-segment-viewport-controller";
import { ViewerHeader } from "@/components/ui/viewer";
import { type SplitView } from "@/components/viewers/lib/split-types";

export interface SplitDocumentHandlers {
  onCurrentPageChange: (page: number) => void;
  onScrollProgressChange: (progress: number) => void;
  setDocumentHandle: (handle: SegmentDocumentHandle | null) => void;
}

export interface SplitViewerProps {
  result: SplitView | null;
  source: ViewerSource;
  isProcessing?: boolean;
  document?: ReactNode;
}

export type SplitViewerSidebarProps = React.ComponentProps<
  typeof FileViewerSidebar
>;

export function SplitViewer({
  result,
  source,
  isProcessing = false,
  document,
}: SplitViewerProps) {
  return (
    <SplitViewerProvider result={result} isProcessing={isProcessing}>
      <FileViewerProvider
        source={source}
        headerMode="outlets"
        defaultSidebarOpen
      >
        <FileViewer className="bg-background">
          <SplitViewerFileHeader />
          <FileViewerContent>
            <SplitViewerSidebar />
            <FileViewerInset>
              <FileViewerLegend>
                <SplitViewerLegend className="px-3 py-2" />
              </FileViewerLegend>
              <SplitViewerDocument document={document} />
            </FileViewerInset>
          </FileViewerContent>
        </FileViewer>
      </FileViewerProvider>
    </SplitViewerProvider>
  );
}

function SplitViewerFileHeader() {
  return (
    <FileViewerHeader>
        <FileViewerSidebarTrigger />
        <FileViewerTitle />
        <FileViewerControls />
    </FileViewerHeader>
  );
}

type SplitViewerContextValue = {
  model: SplitViewerModel;
  viewport: SegmentViewportController;
};

export type SplitViewerModel = {
  hasOutput: boolean;
  isProcessing: boolean;
  pageCount: number;
  segments: DocumentSegment[];
};

type SplitViewerHeaderState = {
  hasOutput: boolean;
  isProcessing: boolean;
  pageCount: number;
  segments: DocumentSegment[];
};

type SplitViewerSidebarState = {
  hasOutput: boolean;
  pageCount: number;
};

type SplitViewerPageRailState = {
  hasOutput: boolean;
  pageCount: number;
  segments: DocumentSegment[];
  viewport: SegmentViewportController;
};

type SplitViewerLegendState = {
  hasOutput: boolean;
  segments: DocumentSegment[];
  viewport: SegmentViewportController;
};

type SplitViewerDocumentState = {
  hasOutput: boolean;
  isProcessing: boolean;
};

const SplitViewerContext = React.createContext<SplitViewerContextValue | null>(
  null,
);

function useSplitViewerContext(): SplitViewerContextValue {
  const context = React.useContext(SplitViewerContext);
  if (!context) {
    throw new Error("useSplitViewer must be used within SplitViewerProvider.");
  }
  return context;
}

function useSplitViewerHeader(): SplitViewerHeaderState {
  return useSplitViewerContext().model;
}

function useSplitViewerSidebar(): SplitViewerSidebarState {
  const { hasOutput, pageCount } = useSplitViewerContext().model;
  return { hasOutput, pageCount };
}

function useSplitViewerPageRail(): SplitViewerPageRailState {
  const { model, viewport } = useSplitViewerContext();
  return {
    hasOutput: model.hasOutput,
    pageCount: model.pageCount,
    segments: model.segments,
    viewport,
  };
}

function useSplitViewerLegend(): SplitViewerLegendState {
  const { model, viewport } = useSplitViewerContext();
  return { hasOutput: model.hasOutput, segments: model.segments, viewport };
}

function useSplitViewerDocument(): SplitViewerDocumentState {
  const { hasOutput, isProcessing } = useSplitViewerContext().model;
  return { hasOutput, isProcessing };
}

export function useSplitViewerDocumentControls(): SplitDocumentHandlers {
  return useSplitViewerContext().viewport.documentHandlers;
}

export function createSplitViewerModel({
  result,
  isProcessing,
}: {
  result: SplitView | null;
  isProcessing: boolean;
}): SplitViewerModel {
  const segments = toSegments(result?.output ?? []) satisfies DocumentSegment[];

  return {
    hasOutput: Boolean(result && result.output.length > 0),
    isProcessing,
    pageCount: segmentsPageCount(segments),
    segments,
  };
}

function createSplitSegmentedDocumentModel(
  model: Pick<SplitViewerModel, "pageCount" | "segments">,
): SegmentedDocumentModel {
  return createSegmentedDocumentModel({
    pageCount: model.pageCount,
    segments: model.segments,
  });
}

export function SplitViewerProvider({
  result,
  isProcessing = false,
  children,
}: {
  result: SplitView | null;
  isProcessing?: boolean;
  children: React.ReactNode;
}) {
  const model = React.useMemo(
    () => createSplitViewerModel({ result, isProcessing }),
    [isProcessing, result],
  );
  const segmentedDocumentModel = React.useMemo(
    () => createSplitSegmentedDocumentModel(model),
    [model],
  );

  return (
    <SegmentedDocumentProvider model={segmentedDocumentModel}>
      <SplitViewerContextProvider model={model}>
        {children}
      </SplitViewerContextProvider>
    </SegmentedDocumentProvider>
  );
}

function SplitViewerContextProvider({
  children,
  model,
}: {
  children: React.ReactNode;
  model: SplitViewerModel;
}) {
  const viewport = useSegmentedDocumentViewport();

  const value = React.useMemo<SplitViewerContextValue>(
    () => ({
      model,
      viewport,
    }),
    [model, viewport],
  );

  return (
    <SplitViewerContext.Provider value={value}>
      {children}
    </SplitViewerContext.Provider>
  );
}

export function SplitViewerHeader() {
  const { hasOutput, isProcessing, pageCount, segments } =
    useSplitViewerHeader();
  const title = hasOutput
    ? `${segments.length} segment${segments.length === 1 ? "" : "s"}`
    : isProcessing
      ? "Splitting"
      : "Split viewer";

  return (
    <ViewerHeader className="flex flex-col">
      <div className="flex min-h-10 items-center justify-between gap-3 px-3 py-2">
        <div className="flex items-center gap-2 text-sm font-medium">
          {hasOutput && pageCount > 0 ? (
            <FileViewerSidebarTrigger className="-ml-1" />
          ) : null}
          <Scissors className="text-muted-foreground size-4" />
          <span>{title}</span>
        </div>
        {hasOutput ? (
          <div className="text-muted-foreground text-xs">
            {pageCount} page{pageCount === 1 ? "" : "s"}
          </div>
        ) : null}
      </div>
    </ViewerHeader>
  );
}

export function SplitViewerSidebar({
  children,
  className,
  width = "4rem",
  "aria-label": ariaLabel = "Split pages",
  ...props
}: SplitViewerSidebarProps) {
  const { hasOutput, pageCount } = useSplitViewerSidebar();
  if (!hasOutput || pageCount <= 0) return null;

  return (
    <FileViewerSidebar
      aria-label={ariaLabel}
      width={width}
      className={cn("border-r", className)}
      {...props}
    >
      <FileViewerSidebarContent className="p-0">
        {children ?? <SplitViewerPageRail />}
      </FileViewerSidebarContent>
    </FileViewerSidebar>
  );
}

export function SplitViewerPageRail() {
  const { hasOutput, pageCount, segments, viewport } = useSplitViewerPageRail();
  if (!hasOutput || pageCount <= 0) return null;

  return (
    <SegmentPageRail
      segments={segments}
      pageCount={pageCount}
      currentPage={viewport.model.currentPage}
      scrollProgress={viewport.model.scrollProgress}
      interaction={viewport.interaction}
      railApi={viewport.rail}
      onSelectPage={viewport.navigation.scrollToPage}
      showTicks
    />
  );
}

export function SplitViewerLegend({ className }: { className?: string }) {
  const { hasOutput, segments, viewport } = useSplitViewerLegend();
  if (!hasOutput) return null;

  return (
    <SegmentLegend
      segments={segments}
      currentPage={viewport.model.currentPage}
      interaction={viewport.interaction}
      onSelect={viewport.navigation.scrollToSegmentStart}
      columns={4}
      variant="plain"
      showUnusedToggle
      className={className}
    />
  );
}

export function SplitViewerDocument({ document }: { document?: ReactNode }) {
  const { hasOutput, isProcessing } = useSplitViewerDocument();

  if (!hasOutput) {
    return <SplitViewerEmptyState isProcessing={isProcessing} />;
  }

  return document ? (
    <FileViewerViewport>{document}</FileViewerViewport>
  ) : (
    <div className="flex h-full flex-1 items-center justify-center">
      <span className="text-muted-foreground text-sm">
        No document available
      </span>
    </div>
  );
}

export function SplitViewerEmptyState({
  isProcessing,
}: {
  isProcessing: boolean;
}) {
  return (
    <div className="bg-background text-muted-foreground flex h-full flex-1 flex-col items-center justify-center gap-4 px-8">
      {isProcessing ? (
        <>
          <Loader2 className="text-warning-foreground h-12 w-12 animate-spin" />
          <p className="text-muted-foreground text-center text-base">
            Splitting...
          </p>
        </>
      ) : (
        <>
          <Scissors className="text-muted-foreground h-16 w-16" />
          <p className="text-muted-foreground text-center text-base">
            Run split to see output
          </p>
          <p className="text-muted-foreground max-w-sm text-center text-sm">
            Upload a document, define subdocuments, then click Run Split
          </p>
        </>
      )}
    </div>
  );
}

import { segmentsPageCount, type Segment } from "@/lib/segments";

export type DocumentSegment = Segment & {
  /** Stable domain id for the item that produced this segment. */
  sourceId?: string;
};

export type SegmentBounds = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export type SegmentAnchor = {
  id: string;
  segmentId: string;
  /** 1-based page/frame number. */
  pageNumber: number;
  /** Normalized page-local rectangle. Omit for whole-page anchors. */
  bounds?: SegmentBounds;
};

export type SegmentedPage = {
  pageNumber: number;
  width?: number;
  height?: number;
};

export type SegmentRow = {
  id: string;
  label?: string;
  /** Generic display grouping only; domain vote/output semantics stay outside. */
  segments: DocumentSegment[];
};

export type SegmentedDocumentModel = {
  pages: SegmentedPage[];
  /** Viewport/navigation projection used for page ownership and jumps. */
  segments: DocumentSegment[];
  /** Optional page-local targets for segment-level navigation and overlays. */
  anchors?: SegmentAnchor[];
  /** Optional generic row projection for visual ribbons or grouped legends. */
  rows?: SegmentRow[];
};

export function createSegmentedDocumentModel({
  anchors,
  pageCount,
  pages,
  rows,
  segments,
}: {
  anchors?: SegmentAnchor[];
  pageCount?: number;
  pages?: SegmentedPage[];
  rows?: SegmentRow[];
  segments: DocumentSegment[];
}): SegmentedDocumentModel {
  return {
    pages:
      pages ?? createSegmentedPages(pageCount ?? segmentsPageCount(segments)),
    segments,
    ...(anchors ? { anchors } : null),
    ...(rows ? { rows } : null),
  };
}

export function createSegmentedPages(pageCount: number): SegmentedPage[] {
  const count =
    Number.isFinite(pageCount) && pageCount > 0 ? Math.floor(pageCount) : 0;
  return Array.from({ length: count }, (_, index) => ({
    pageNumber: index + 1,
  }));
}

"use client";

import * as React from "react";

import type { SegmentedDocumentModel } from "./segmented-document-model";
import {
  useSegmentViewportController,
  type SegmentedDocumentViewport,
} from "./use-segment-viewport-controller";

type SegmentedDocumentContextValue = {
  model: SegmentedDocumentModel;
  viewport: SegmentedDocumentViewport;
};

const SegmentedDocumentContext =
  React.createContext<SegmentedDocumentContextValue | null>(null);

export function SegmentedDocumentProvider({
  children,
  model,
}: {
  children: React.ReactNode;
  model: SegmentedDocumentModel;
}) {
  const viewport = useSegmentViewportController({ segments: model.segments });
  const value = React.useMemo<SegmentedDocumentContextValue>(
    () => ({ model, viewport }),
    [model, viewport],
  );

  return (
    <SegmentedDocumentContext.Provider value={value}>
      {children}
    </SegmentedDocumentContext.Provider>
  );
}

function useSegmentedDocumentContext(): SegmentedDocumentContextValue {
  const context = React.useContext(SegmentedDocumentContext);
  if (!context) {
    throw new Error("SegmentedDocumentProvider context is missing.");
  }
  return context;
}

export function useSegmentedDocumentViewport(): SegmentedDocumentViewport {
  return useSegmentedDocumentContext().viewport;
}

export function useSegmentedDocumentModel(): SegmentedDocumentModel {
  return useSegmentedDocumentContext().model;
}

"use client";

import * as React from "react";
import { useMountEffect } from "@/hooks/use-mount-effect";

import {
  getSegmentInteractionState,
  type SegmentInteraction,
  type SegmentInteractionState,
} from "@/lib/segment-interaction";
import { firstSegmentPage, type Segment } from "@/lib/segments";

import type {
  DocumentSegment,
  SegmentAnchor,
} from "./segmented-document-model";
import { useSegmentInteraction } from "./use-segment-interaction";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

const RAIL_VISIBILITY_MARGIN = 24;
const PROGRAMMATIC_SCROLL_WINDOW_MS = 120;
const USER_SCROLL_IDLE_MS = 400;

export interface SegmentViewportModel extends SegmentInteractionState {
  scrollProgress: number;
}

export type SegmentDocumentHandle = {
  getViewportElement?: () => HTMLElement | null;
  scrollToPage: (page: number, options?: ScrollToOptions) => void;
  scrollToAnchor?: (anchor: SegmentAnchor, options?: ScrollToOptions) => void;
  scrollToPageArea?: (
    target: {
      pageNumber: number;
      top: number;
      left?: number;
      width?: number;
      height?: number;
    },
    options?: ScrollToOptions,
  ) => void;
};

export type SegmentNavigationOptions = ScrollToOptions & {
  clearPreview?: boolean;
};

export interface SegmentViewportController {
  model: SegmentViewportModel;
  interaction: SegmentInteraction;
  documentHandlers: {
    onCurrentPageChange: (page: number) => void;
    onScrollProgressChange: (progress: number) => void;
    setDocumentHandle: (handle: SegmentDocumentHandle | null) => void;
  };
  navigation: {
    scrollToPage: (page: number, options?: SegmentNavigationOptions) => void;
    scrollToSegmentStart: (
      segment: DocumentSegment,
      options?: SegmentNavigationOptions,
    ) => void;
    scrollToAnchor: (
      anchor: SegmentAnchor,
      options?: SegmentNavigationOptions,
    ) => void;
  };
  rail: {
    setViewportElement: (element: HTMLElement | null) => void;
    setPageElement: (page: number, element: HTMLElement | null) => void;
    onPointerEnter: () => void;
    onPointerLeave: () => void;
    onScroll: () => void;
  };
}

interface RailFollowState {
  isPointerInsideRail: boolean;
  isUserScrollingRail: boolean;
  lastProgrammaticScrollAt: number;
  idleTimer: number | null;
}

export function useSegmentViewportController({
  segments,
}: {
  segments: Segment[];
}): SegmentViewportController {
  const [currentPage, setCurrentPage] = React.useState<number | null>(1);
  const [scrollProgress, setScrollProgress] = React.useState(0);
  const documentHandleRef = React.useRef<SegmentDocumentHandle | null>(null);
  const interaction = useSegmentInteraction();
  const { clearPreview } = interaction;
  const railViewportRef = React.useRef<HTMLElement | null>(null);
  const pageElementByNumberRef = React.useRef(new Map<number, HTMLElement>());
  const railFollowStateRef = React.useRef<RailFollowState>({
    isPointerInsideRail: false,
    isUserScrollingRail: false,
    lastProgrammaticScrollAt: 0,
    idleTimer: null,
  });

  const model = React.useMemo<SegmentViewportModel>(() => {
    const interactionState = getSegmentInteractionState({
      segments,
      currentPage,
      interaction,
    });

    return {
      ...interactionState,
      scrollProgress,
    };
  }, [currentPage, interaction, scrollProgress, segments]);

  const onCurrentPageChange = React.useCallback((page: number) => {
    setCurrentPage(normalizePage(page));
  }, []);

  const onScrollProgressChange = React.useCallback((progress: number) => {
    setScrollProgress(clamp01(progress));
  }, []);

  const setDocumentHandle = React.useCallback(
    (handle: SegmentDocumentHandle | null) => {
      documentHandleRef.current = handle;
    },
    [],
  );

  const scrollToPage = React.useCallback(
    (page: number, options?: SegmentNavigationOptions) => {
      const normalizedPage = normalizePage(page);
      if (normalizedPage == null) return;

      if (options?.clearPreview !== false) interaction.clearPreview();
      const scrollOptions = segmentScrollOptions(options);
      if (scrollOptions) {
        documentHandleRef.current?.scrollToPage(normalizedPage, scrollOptions);
      } else {
        documentHandleRef.current?.scrollToPage(normalizedPage);
      }
    },
    [interaction],
  );

  const scrollToSegmentStart = React.useCallback(
    (segment: DocumentSegment, options?: SegmentNavigationOptions) => {
      const page = firstSegmentPage(segment.pages);
      if (page == null) return;

      scrollToPage(page, options);
    },
    [scrollToPage],
  );

  const scrollToAnchor = React.useCallback(
    (anchor: SegmentAnchor, options?: SegmentNavigationOptions) => {
      const normalizedPage = normalizePage(anchor.pageNumber);
      if (normalizedPage == null) return;

      if (options?.clearPreview !== false) interaction.clearPreview();
      const scrollOptions = segmentScrollOptions(options);
      const handle = documentHandleRef.current;
      if (!handle) return;

      if (handle.scrollToAnchor) {
        if (scrollOptions) {
          handle.scrollToAnchor(anchor, scrollOptions);
        } else {
          handle.scrollToAnchor(anchor);
        }
        return;
      }

      if (anchor.bounds && handle.scrollToPageArea) {
        const target = {
          pageNumber: normalizedPage,
          left: toPageAreaPercent(anchor.bounds.x),
          top: toPageAreaPercent(anchor.bounds.y),
          width: toPageAreaPercent(anchor.bounds.width),
          height: toPageAreaPercent(anchor.bounds.height),
        };
        if (scrollOptions) {
          handle.scrollToPageArea(target, scrollOptions);
        } else {
          handle.scrollToPageArea(target);
        }
        return;
      }

      if (scrollOptions) {
        handle.scrollToPage(normalizedPage, scrollOptions);
      } else {
        handle.scrollToPage(normalizedPage);
      }
    },
    [interaction],
  );

  const followCurrentPage = React.useCallback((page: number | null) => {
    const normalizedPage = normalizePage(page);
    if (normalizedPage == null) return;

    const state = railFollowStateRef.current;
    if (state.isPointerInsideRail || state.isUserScrollingRail) return;

    const viewport = railViewportRef.current;
    const target = pageElementByNumberRef.current.get(normalizedPage);
    if (!viewport || !target) return;

    const viewportRect = viewport.getBoundingClientRect();
    const targetRect = target.getBoundingClientRect();
    const minTop = viewportRect.top + RAIL_VISIBILITY_MARGIN;
    const maxBottom = viewportRect.bottom - RAIL_VISIBILITY_MARGIN;

    if (targetRect.top >= minTop && targetRect.bottom <= maxBottom) return;

    const targetTop =
      target.offsetTop - viewport.clientHeight / 2 + target.offsetHeight / 2;

    state.lastProgrammaticScrollAt = performance.now();
    viewport.scrollTo?.({
      top: Math.max(0, targetTop),
      behavior: "smooth",
    });
  }, []);

  useKeyedLayoutEffect(joinEffectKey([currentPage, followCurrentPage]), () => {
    followCurrentPage(currentPage);
  });

  useMountEffect(() => {
    const state = railFollowStateRef.current;
    return () => {
      const timer = state.idleTimer;
      if (timer != null) window.clearTimeout(timer);
    };
  });

  useKeyedMountEffect(joinEffectKey([clearPreview, segments]), () => {
    setCurrentPage(1);
    setScrollProgress(0);
    clearPreview();
  });

  const setPageElement = React.useCallback(
    (page: number, element: HTMLElement | null) => {
      const normalizedPage = normalizePage(page);
      if (normalizedPage == null) return;

      if (element) {
        pageElementByNumberRef.current.set(normalizedPage, element);
      } else {
        pageElementByNumberRef.current.delete(normalizedPage);
      }
    },
    [],
  );

  const handleRailScroll = React.useCallback(() => {
    const state = railFollowStateRef.current;
    const elapsed = performance.now() - state.lastProgrammaticScrollAt;
    if (elapsed < PROGRAMMATIC_SCROLL_WINDOW_MS) return;

    state.isUserScrollingRail = true;
    if (state.idleTimer != null) window.clearTimeout(state.idleTimer);
    state.idleTimer = window.setTimeout(() => {
      state.isUserScrollingRail = false;
      state.idleTimer = null;
    }, USER_SCROLL_IDLE_MS);
  }, []);

  const rail = React.useMemo(
    () => ({
      setViewportElement: (element: HTMLElement | null) => {
        railViewportRef.current = element;
      },
      setPageElement,
      onPointerEnter: () => {
        railFollowStateRef.current.isPointerInsideRail = true;
      },
      onPointerLeave: () => {
        railFollowStateRef.current.isPointerInsideRail = false;
      },
      onScroll: handleRailScroll,
    }),
    [handleRailScroll, setPageElement],
  );

  const documentHandlers = React.useMemo(
    () => ({
      onCurrentPageChange,
      onScrollProgressChange,
      setDocumentHandle,
    }),
    [onCurrentPageChange, onScrollProgressChange, setDocumentHandle],
  );

  const navigation = React.useMemo(
    () => ({
      scrollToPage,
      scrollToAnchor,
      scrollToSegmentStart,
    }),
    [scrollToAnchor, scrollToPage, scrollToSegmentStart],
  );

  return React.useMemo(
    () => ({
      model,
      interaction,
      documentHandlers,
      navigation,
      rail,
    }),
    [documentHandlers, interaction, model, navigation, rail],
  );
}

function normalizePage(page: number | null | undefined): number | null {
  return page != null && Number.isInteger(page) && page > 0 ? page : null;
}

function clamp01(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.min(1, Math.max(0, value));
}

function toPageAreaPercent(value: number): number {
  if (!Number.isFinite(value)) return 0;
  return value >= 0 && value <= 1 ? value * 100 : value;
}

function segmentScrollOptions(
  options: SegmentNavigationOptions | undefined,
): ScrollToOptions | undefined {
  if (!options) return undefined;
  const { clearPreview: _clearPreview, ...scrollOptions } = options;
  return Object.keys(scrollOptions).length > 0 ? scrollOptions : undefined;
}

export type SegmentedDocumentViewportModel = SegmentViewportModel;
export type SegmentedDocumentHandle = SegmentDocumentHandle;
export type SegmentedDocumentViewport = SegmentViewportController;
export type SegmentedDocumentHandlers =
  SegmentViewportController["documentHandlers"];
export type SegmentedDocumentNavigation =
  SegmentViewportController["navigation"];
